// Content with portions generated by generative AI platform
package org.eclipse.kura.linux.watchdog;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.CyclicBarrier;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;

import org.junit.After;
import org.junit.Before;
import org.junit.Test;

public class CriticalComponentConcurrencyTest {

    private static final String REBOOT_CAUSE_FILE = "target/criticalComponentConcurrencyRebootCause";
    private static final String COMPONENT_NAME = "concurrentComponent";
    private static final int PING_INTERVAL_MS = 5;
    private static final int COMPONENT_TIMEOUT_MS = 500;
    private static final int THREADS = 8;
    private static final long CHECKIN_DURATION_MS = 1500;
    private static final int REGISTRATION_ROUNDS = 200;
    private static final long REBOOT_WAIT_TIMEOUT_MS = 10000;
    private static final long TASK_TIMEOUT_SEC = 30;

    private final ExecutorService workers = Executors.newFixedThreadPool(THREADS);
    private final List<SupervisionTestWatchdogServiceImpl> services = new ArrayList<>();
    private final List<Integer> registrationCounts = new ArrayList<>();
    private SupervisionTestWatchdogServiceImpl svc;
    private TestCC component;

    @Test
    public void concurrentCheckinsDoNotCauseSpuriousTimeout() throws Exception {
        givenSupervisedComponent();

        whenComponentChecksInConcurrentlyFor(CHECKIN_DURATION_MS);

        thenNoRebootIsRequested();
    }

    @Test
    public void componentThatStopsCheckingInTimesOut() throws Exception {
        givenSupervisedComponent();

        whenComponentChecksInConcurrentlyFor(CHECKIN_DURATION_MS);

        thenRebootIsRequested();
        thenRebootCauseIs(COMPONENT_NAME);
    }

    @Test
    public void concurrentRegistrationsOfSameComponentCreateOneRegistration() throws Exception {
        givenComponent();

        whenComponentIsRegisteredConcurrently(REGISTRATION_ROUNDS);

        thenEveryRoundHasRegistrations(1);
    }

    @Before
    public void deleteRebootCauseFileBefore() {
        new File(REBOOT_CAUSE_FILE).delete();
    }

    @After
    public void cleanup() {
        this.workers.shutdownNow();
        for (SupervisionTestWatchdogServiceImpl service : this.services) {
            service.deactivate();
        }
        new File(REBOOT_CAUSE_FILE).delete();
    }

    private void givenComponent() {
        this.component = new TestCC(COMPONENT_NAME, COMPONENT_TIMEOUT_MS);
    }

    private void givenSupervisedComponent() {
        givenComponent();
        this.svc = newService(true);
        this.svc.registerCriticalComponent(this.component);
    }

    private void whenComponentChecksInConcurrentlyFor(final long durationMs) throws Exception {
        final long deadline = System.nanoTime() + TimeUnit.MILLISECONDS.toNanos(durationMs);
        final List<Future<?>> futures = new ArrayList<>();
        for (int i = 0; i < THREADS; i++) {
            futures.add(this.workers.submit(() -> {
                while (System.nanoTime() - deadline < 0) {
                    this.svc.checkin(this.component);
                    Thread.yield();
                }
            }));
        }
        for (Future<?> future : futures) {
            future.get(TASK_TIMEOUT_SEC, TimeUnit.SECONDS);
        }
    }

    private void whenComponentIsRegisteredConcurrently(final int rounds) throws Exception {
        for (int round = 0; round < rounds; round++) {
            final SupervisionTestWatchdogServiceImpl service = newService(false);
            final CyclicBarrier barrier = new CyclicBarrier(THREADS);
            final List<Future<?>> futures = new ArrayList<>();
            for (int i = 0; i < THREADS; i++) {
                futures.add(this.workers.submit(() -> {
                    barrier.await(TASK_TIMEOUT_SEC, TimeUnit.SECONDS);
                    service.registerCriticalComponent(this.component);
                    return null;
                }));
            }
            for (Future<?> future : futures) {
                future.get(TASK_TIMEOUT_SEC, TimeUnit.SECONDS);
            }
            this.registrationCounts.add(service.getCriticalComponents().size());
            service.deactivate();
            this.services.remove(service);
        }
    }

    private void thenNoRebootIsRequested() {
        assertEquals(0, this.svc.getRebootRequests());
    }

    private void thenRebootIsRequested() throws InterruptedException {
        assertTrue(this.svc.awaitRebootRequest(REBOOT_WAIT_TIMEOUT_MS));
    }

    private void thenRebootCauseIs(final String expectedCause) throws IOException {
        final List<String> lines = Files.readAllLines(new File(REBOOT_CAUSE_FILE).toPath());
        assertEquals(2, lines.size());
        assertEquals(expectedCause, lines.get(1));
    }

    private void thenEveryRoundHasRegistrations(final int expectedRegistrations) {
        assertEquals(REGISTRATION_ROUNDS, this.registrationCounts.size());
        for (int i = 0; i < this.registrationCounts.size(); i++) {
            assertEquals("round " + i, expectedRegistrations, (int) this.registrationCounts.get(i));
        }
    }

    private SupervisionTestWatchdogServiceImpl newService(final boolean enabled) {
        final Map<String, Object> properties = new HashMap<>();
        properties.put("enabled", enabled);
        properties.put("watchdogMode", "fallback");
        properties.put("pingInterval", PING_INTERVAL_MS);
        properties.put("rebootCauseFilePath", REBOOT_CAUSE_FILE);
        final SupervisionTestWatchdogServiceImpl service = new SupervisionTestWatchdogServiceImpl();
        service.activate(properties);
        this.services.add(service);
        return service;
    }
}
